// Step 1: Build the request body for OpenRouter with tool definitions
const chatInput = $input.first().json.chatInput;

const systemPrompt = `Tu es un assistant intelligent. Tu as accès à un calculateur et à Wikipedia.
Utilise tes outils quand c'est pertinent. Réponds en français.`;

const messages = [
  { role: 'system', content: systemPrompt },
  { role: 'user', content: chatInput }
];

const tools = [
  {
    type: 'function',
    function: {
      name: 'calculator',
      description: 'Evaluate a mathematical expression. Use this for any calculation.',
      parameters: {
        type: 'object',
        properties: {
          expression: {
            type: 'string',
            description: 'The math expression to evaluate, e.g. 0.15 * 847'
          }
        },
        required: ['expression']
      }
    }
  },
  {
    type: 'function',
    function: {
      name: 'wikipedia',
      description: 'Search Wikipedia for information about a topic. Use this for factual questions.',
      parameters: {
        type: 'object',
        properties: {
          query: {
            type: 'string',
            description: 'The topic to search on Wikipedia (e.g. Alan Turing)'
          }
        },
        required: ['query']
      }
    }
  }
];

const requestBody = {
  model: 'mistralai/mistral-small-3.1-24b-instruct:free',
  messages: messages,
  tools: tools,
  temperature: 0
};

return [{ json: { requestBody, messages } }];

// Step 3: Parse the LLM response — tool call or direct answer?
const response = $input.first().json;
const prevMessages = $('1. Build Request').first().json.messages;
const choice = response.choices?.[0]?.message;

if (!choice) {
  // Malformed response — return error
  return [{ json: {
    hasToolCall: false,
    directAnswer: 'Erreur : réponse inattendue du modèle.',
    messages: prevMessages
  }}];
}

const toolCalls = choice.tool_calls;

if (toolCalls && toolCalls.length > 0) {
  const tc = toolCalls[0];
  let args;
  try {
    args = JSON.parse(tc.function.arguments);
  } catch (e) {
    args = {};
  }
  return [{ json: {
    hasToolCall: true,
    toolName: tc.function.name,
    toolArgs: args,
    toolCallId: tc.id,
    assistantMessage: choice,
    messages: prevMessages,
    directAnswer: null
  }}];
} else {
  return [{ json: {
    hasToolCall: false,
    directAnswer: choice.content || 'Pas de réponse.',
    messages: prevMessages
  }}];
}

// Direct answer path — no tool call needed
const answer = $input.first().json.directAnswer;
return [{ json: { output: answer } }];

// Calculator: evaluate the math expression
const data = $input.first().json;
const expression = data.toolArgs?.expression || '0';

let result;
try {
  // Simple arithmetic evaluation using Function constructor
  // Safe in this context: teacher-controlled demo, not user-facing production
  const sanitized = expression.replace(/[^0-9+\-*/.() ]/g, '');
  result = String(Function('"use strict"; return (' + sanitized + ')')());
} catch (e) {
  result = 'Expression invalide: ' + expression;
}

return [{ json: {
  toolResult: result,
  toolName: data.toolName,
  toolCallId: data.toolCallId,
  assistantMessage: data.assistantMessage,
  messages: data.messages
}}];

// Extract Wikipedia summary and pass through tool call context
const wikiResp = $input.first().json;
const prevData = $('5b. Which Tool?').first().json;

let summary;
if (wikiResp.extract) {
  summary = wikiResp.title + ' — ' + wikiResp.extract;
} else {
  summary = 'Aucun article trouvé pour: ' + (prevData.toolArgs?.query || 'inconnu');
}

return [{ json: {
  toolResult: summary,
  toolName: prevData.toolName,
  toolCallId: prevData.toolCallId,
  assistantMessage: prevData.assistantMessage,
  messages: prevData.messages
}}];

// Build the tool result message to send back to the LLM
const data = $input.first().json;

const updatedMessages = [
  ...data.messages,
  data.assistantMessage,
  {
    role: 'tool',
    tool_call_id: data.toolCallId,
    content: data.toolResult
  }
];

const requestBody = {
  model: 'mistralai/mistral-small-3.1-24b-instruct:free',
  messages: updatedMessages,
  temperature: 0
};

return [{ json: { requestBody } }];

// Extract the final answer from the second LLM call
const response = $input.first().json;
const content = response.choices?.[0]?.message?.content || 'Erreur : pas de réponse du modèle.';
return [{ json: { output: content } }];
